// ===================================================================
//  ⚙️  Everything Linda needs to know. Edit this node, nothing else.
//  DEMO: point her chat at YOUR Telegram, so "Thinking of you" lands on
//  your phone and you can reply to it yourself. Swap her chat id in for real.
// ===================================================================
const cfg = {
  her: {
    name:  'Pookie',
    telegram_chat: 'YOUR_TELEGRAM_CHAT_ID',
    work:  { name: 'her work (the café on Oxford St, Leederville)', lat: -31.9365, lon: 115.8418 },
  },
  me:          { name: 'Aaron', telegram_chat: 'YOUR_TELEGRAM_CHAT_ID' },
  flowers: {
    order:           '12 pink roses',
    card:            'Thinking of you. x',
    deliver_by:      '4:30pm',
    search_radius_m: 2500,
    order_inbox:     'you@example.com',   // DEMO: the order comes to you, not the shop
    fallback_florist: { name: 'Your usual florist', email: '', website: '' },
  },
  boys_night:    { match: 'boys', move_days: 7 },
  comfort_order: { store: "Grill'd", items: ['Mustard & Pickled!', 'Sweet Potato Chips'], at: '5:30pm' },
  movies:        { country: 'AU', service: 'Netflix' },
};

// The box "Find the closest florist" searches: her work, +/- search_radius_m.
const w = cfg.her.work, r = cfg.flowers.search_radius_m;
const dLat = r / 111320, dLon = r / (111320 * Math.cos(w.lat * Math.PI / 180));
cfg.search_box = [w.lon - dLon, w.lat + dLat, w.lon + dLon, w.lat - dLat].map(n => n.toFixed(5)).join(',');
return [{ json: cfg }];

// ===================================================================
//  📱 What her iPhone Shortcut posts when she plugs her phone in.
//  Apple Health > Cycle Tracking > Find Health Samples (Menstrual Flow).
//  DEMO STUB: in the full build this is the "Her cycle" webhook.
//  Same fields. Her last period started 14 days ago.
// ===================================================================
const DAY = 86400000;
const today = Date.parse(new Date().toLocaleDateString('en-CA', { timeZone: 'Australia/Perth' }));
return [{ json: {
  source:            'Apple Health · Cycle Tracking',
  last_period_start: new Date(today - 14 * DAY).toISOString().slice(0, 10),
  logged_flow_days:  5,
  avg_cycle_days:    28,
} }];

// ===================================================================
//  Where is she in her cycle?
//  Luteal phase = the ~14 days between ovulation and her next period.
//  So luteal day 1 is (next period - 14 days), which for a 28-day
//  cycle is cycle day 15.
// ===================================================================
const c = $input.first().json.body || $input.first().json;
const DAY = 86400000;
const iso = d => new Date(d).toISOString().slice(0, 10);

const today = Date.parse(new Date().toLocaleDateString('en-CA', { timeZone: 'Australia/Perth' }));
const start = Date.parse(c.last_period_start);
const len = Number(c.avg_cycle_days) || 28;
if (!isFinite(start)) throw new Error('No period start came through from her Shortcut');

const cycleDay = (Math.floor((today - start) / DAY) % len) + 1;
const lutealFrom = len - 13;                 // day 15 of a 28-day cycle
const nextPeriod = start + Math.ceil((today - start + 1) / (len * DAY)) * len * DAY;

return [{ json: {
  cycle_day:      cycleDay,
  phase:          cycleDay <= 5 ? 'period' : cycleDay < lutealFrom ? 'follicular' : 'luteal',
  luteal_day_1:   iso(nextPeriod - 14 * DAY),
  next_period:    iso(nextPeriod),
  days_to_period: Math.round((nextPeriod - today) / DAY),
  luteal_today:   cycleDay === lutealFrom,
} }];

// ===================================================================
//  Has she replied yet?
//  Reads the bot's real Telegram updates for a message in her chat
//  sent AFTER "Thinking of you" went out. No reply = hold 3s, ask again.
// ===================================================================
const cfg = $('⚙️ Linda settings').first().json;
const sentAt = $('Text her: Thinking of you ❤️').first().json.result.date;   // unix seconds

let reply = null;
for (const u of ($input.first().json.result || [])) {
  const m = u.message;
  if (m && String(m.chat.id) === String(cfg.her.telegram_chat) && m.date >= sentAt && m.text
      && !(m.from && m.from.is_bot)) reply = m;                    // last one wins
}
// Test hook: the webhook trigger can pass a reply so the run can be verified hands-free.
if (!reply) { try { const t = $('Webhook (test)').first().json.body.test_reply; if (t) reply = { text: t }; } catch (e) {} }

const waited = ($runIndex || 0) * 3;
if (!reply && waited > 300) throw new Error('No reply after 5 minutes. Reply in Telegram, then run it again.');

return [{ json: {
  replied:    !!reply,
  her_reply:  reply ? reply.text : 'waiting for her reply...',
  waited_sec: waited,
} }];

// ===================================================================
//  Closest florist to where she works, from OpenStreetMap (Nominatim).
//  Free, keyless, real shops. OSM often lists the shop's email; if it
//  doesn't, the next node reads it off the florist's own website.
// ===================================================================
const cfg = $('⚙️ Linda settings').first().json;
const w = cfg.her.work;
const rad = Math.PI / 180;
const km = (a, b) => {
  const x = Math.sin((b.lat - a.lat) * rad / 2) ** 2 +
            Math.cos(a.lat * rad) * Math.cos(b.lat * rad) * Math.sin((b.lon - a.lon) * rad / 2) ** 2;
  return 6371 * 2 * Math.asin(Math.sqrt(x));
};

// n8n hands a JSON array over as one item per result
const shops = $input.all().map(i => i.json).filter(e => e && e.lat).map(e => {
  const t = Object.assign({}, e.extratags || {}, e.address || {});
  t.name = e.name;
  const p = { lat: Number(e.lat), lon: Number(e.lon) };
  return {
    name:    t.name,
    km:      p.lat ? +km(w, p).toFixed(2) : 999,
    email:   t.email || t['contact:email'] || '',
    website: t.website || t['contact:website'] || '',
    phone:   t.phone || t['contact:phone'] || '',
    address: [t['addr:housenumber'], t['addr:street'], t['addr:suburb']].filter(Boolean).join(' '),
  };
}).filter(s => s.name && s.km < 999).sort((a, b) => a.km - b.km);

const found = shops.length;
// OpenStreetMap down or nothing nearby? Use the florist you set up as a fallback.
if (!shops.length) shops.push(Object.assign({ km: null, fallback: true }, cfg.flowers.fallback_florist));
return [{ json: Object.assign({ florists_found: found }, shops[0]) }];

// ===================================================================
//  Write the order. Goes to the florist's own email in the full build.
//  DEMO: order_inbox is set, so it comes to your inbox instead.
// ===================================================================
const cfg = $('⚙️ Linda settings').first().json;
const f = $input.first().json;
const html =
  '<p>Hi ' + f.name + ' team,</p>' +
  '<p>Could I please order <b>' + cfg.flowers.order + '</b> for delivery <b>today, before ' +
  cfg.flowers.deliver_by + '</b>, to ' + cfg.her.name + ' at ' + cfg.her.work.name + '.</p>' +
  '<p>Card message: <i>"' + cfg.flowers.card + '"</i></p>' +
  '<p>Please charge the card you have on file for me. Thanks so much!</p>' +
  '<p>' + cfg.me.name + '</p>';
return [{ json: {
  florist: f.name, km: f.km,
  send_to: cfg.flowers.order_inbox || f.email,
  subject: 'Flower order for today: ' + cfg.flowers.order,
  html: html,
} }];

// ===================================================================
//  DEMO STUB for two Google Calendar nodes in the full build:
//  Get many events (this Friday, matching "boys") -> Update each one,
//  start + end moved 7 days. Updating an event emails the boys.
// ===================================================================
const fmt = d => d.toLocaleDateString('en-AU', { weekday: 'short', day: 'numeric', month: 'short', timeZone: 'Australia/Perth' });
const now = new Date();
const fri = new Date(now.getTime() + ((5 - now.getDay() + 7) % 7) * 86400000);
return [{ json: {
  event:          "Boys' night @ The Royal",
  was:            fmt(fri) + ', 7:00pm',
  now:            fmt(new Date(fri.getTime() + 7 * 86400000)) + ', 7:00pm',
  invites_updated: ['Davo', 'Mick', 'Tommo'],
} }];

// ===================================================================
//  DEMO STUB for "Order Grill'd (Browserless)" in the full build.
//  Grill'd has no ordering API, so a headless browser logs into your
//  Grill'd account, reorders the saved favourite and pays with the
//  saved card. Pickup, because the courier collects it.
// ===================================================================
const cfg = $('⚙️ Linda settings').first().json;
return [{ json: {
  store:   cfg.comfort_order.store + ' (closest store)',
  items:   cfg.comfort_order.items,
  order:   'pickup, paid, ready in 15 min',
  for:     cfg.me.name,
} }];

// ===================================================================
//  DEMO STUB for Uber Direct. Full build: POST
//  /v1/customers/{id}/deliveries, pickup at Grill'd, drop-off at hers.
//  Uber Direct's sandbox has a robot courier that walks the delivery
//  through every status without a real driver.
// ===================================================================
const cfg = $('⚙️ Linda settings').first().json;
return [{ json: {
  delivery_id:  'del_' + Math.random().toString(36).slice(2, 12),
  status:       'pending',
  pickup:       $input.first().json.store,
  dropoff:      cfg.her.name + "'s place",
  pickup_notes: 'Order under ' + cfg.me.name + ': ' + cfg.comfort_order.items.join(' + '),
} }];

// ===================================================================
//  DEMO STUB for the Uber Direct webhook. This is the payload it
//  posts when the driver picks up: status pickup_complete. In the full
//  build that event is the trigger for the movie lane.
// ===================================================================
return [{ json: {
  kind:        'event.delivery_status',
  status:      'pickup_complete',
  delivery_id: $input.first().json.delivery_id,
  courier:     { name: 'Sam', vehicle_type: 'car' },
  eta_min:     12,
} }];

// ===================================================================
//  Her Netflix history. Netflix has no API, so she downloads Viewing
//  Activity as a CSV and it lives in a Google Sheet. DEMO STUB:
//  the rows from that CSV.
// ===================================================================
return [{ json: {
  source: 'Netflix > Viewing activity (CSV)',
  watched: [
    'Barbie', 'Mean Girls', 'The Proposal', 'Crazy Rich Asians', 'The Devil Wears Prada',
    'Gilmore Girls: Season 1: Pilot', 'Emily in Paris: Season 4: Got Ghosted',
    'Bridgerton: Season 3: Out of the Shadows', 'Reminders of Him', 'The Gentlemen',
  ],
} }];

// ===================================================================
//  Fresh on Netflix vs what she's already watched.
//  Netflix's Viewing Activity CSV writes episodes as
//  "Show: Season 1: Episode", so compare on the part before the colon.
// ===================================================================
const norm = s => String(s || '').toLowerCase().split(':')[0].replace(/[^a-z0-9]/g, '');
const watched = new Set(($('Her Netflix history').first().json.watched || []).map(norm));

const scraped = $('Apify: new on Netflix AU').all().map(i => i.json).filter(m => m.title);
const fresh = scraped.filter(m => !watched.has(norm(m.title)) && !watched.has(norm(m.originalTitle)));

const lines = fresh.map(m => '- ' + m.title + ' · ' + (m.releaseYear || '?') + ' · ' +
  (m.genres || []).join(', ') + ' · IMDb ' + (m.imdbScore || '?') + ' · ' +
  String(m.shortDescription || '').slice(0, 160));

return [{ json: {
  scraped:         scraped.length,
  already_watched: scraped.length - fresh.length,
  candidates:      fresh.length,
  candidates_text: lines.join('\n'),
} }];

